const size={width:640,height:480};
export type OpenRenderScene='outside'|'inside'|'map'|'cavity'|'axial'|'hole';
const digest=async(values:Float32Array)=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',values.slice().buffer))].map(v=>v.toString(16).padStart(2,'0')).join('');
function node(label:string){const box=document.createElement('figure'),caption=document.createElement('figcaption'),canvas=document.createElement('canvas');caption.textContent=label;box.style.margin='0';canvas.style.cssText='width:640px;height:480px;background:#0b1821';box.append(caption,canvas);document.querySelector('#open-render')!.append(box);return canvas;}
function compare(cpu:Uint8ClampedArray,gpu:Uint8ClampedArray,width:number,height:number){
 const a=(i:number,c:number)=>c===3?cpu[i+3]!:cpu[i+c]!*cpu[i+3]!/255,b=(i:number,c:number)=>gpu[i+c]!;let checked=0,stableChecked=0,stableMax=0,envelopeMax=0,envelopeViolations=0,total=0;const worst:{x:number;y:number;error:number;cpu:number[];gpu:number[]}[]=[];
 for(let y=3;y<height-3;y+=2)for(let x=3;x<width-3;x+=2){const at=(y*width+x)*4;if(!cpu[at+3]&&!gpu[at+3])continue;checked++;let opaque=cpu[at+3]===255&&gpu[at+3]===255,variation=0,err=0,bad=false;
  for(let c=0;c<4;c++){let lo=Infinity,hi=-Infinity;for(const dy of[-2,0,2])for(const dx of[-2,0,2]){const i=((y+dy)*width+x+dx)*4,v=a(i,c);lo=Math.min(lo,v);hi=Math.max(hi,v);opaque&&=cpu[i+3]===255;}const error=Math.max(lo-b(at,c),b(at,c)-hi,0);envelopeMax=Math.max(envelopeMax,error);bad||=error>3;variation=Math.max(variation,hi-lo);err=Math.max(err,Math.abs(a(at,c)-b(at,c)));}
  if(bad){envelopeViolations++;if(worst.length<12)worst.push({x,y,error:err,cpu:[...cpu.subarray(at,at+4)],gpu:[...gpu.subarray(at,at+4)]});}total+=err;if(opaque&&variation<=12){stableChecked++;stableMax=Math.max(stableMax,err);}
 }
 return{checked,stableChecked,stableMax,envelopeMax,envelopeViolations,meanError:total/Math.max(1,checked),worst};
}
