 const t=createOpenCylinderTerrain({terrainId:'open-render-source',geometry:{identity:{worldId:'open-render',surfaceId:'one-connected-boundary'},provider:'physical-open-cylinder',version:1,configuration:'both-open',outerRadiusMeters:1000000,innerRadiusMeters:500000,lengthMeters:1600000},resolution:{angularSamples:n,axialCells:n/2,radialCells:n/4},initialElevation:-100});
 for(const[patchId,u,v]of[['outer-wall',0,800000],['inner-wall',0,800000],['rim-end',0,250000],['rim-start',1,250000]]as const){const job=prepareOpenCylinderDab(t,{...t.metadata.identity,patchId,u,v},{version:1,tool:'raise',radiusMeters:70000,strengthMeters:2000});while(job.status==='preparing')job.pump(64);job.commit();}
