 const reference=openCylinderReferenceModel(t.geometry),theta=.6,model=scene==='hole'?{...reference,primitives:[{a:[1.12*Math.cos(theta),1.12*Math.sin(theta),0]as const,b:[.35*Math.cos(theta),.35*Math.sin(theta),0]as const,radius:.05}]}:reference,dimensions=surfaceDisplayDimensions(size,scene==='cavity'||scene==='hole'?Math.max(devicePixelRatio,1.5):devicePixelRatio),left=node(`Open Cylinder N${n} ${scene}: accepted Canvas terrain pass`),right=node(`Same authority / camera: actual WebGL2 terrain pass`);
