 if(!renderer.available)throw Error(renderer.statistics.reason);const present=performance.now();renderer.present(view,size,'relief');const presentMs=performance.now()-present,gl=right.getContext('webgl2')!,raw=new Uint8Array(right.width*right.height*4),pixels=new Uint8ClampedArray(raw.length);gl.readPixels(0,0,right.width,right.height,gl.RGBA,gl.UNSIGNED_BYTE,raw);for(let y=0;y<right.height;y++)pixels.set(raw.subarray((right.height-y-1)*right.width*4,(right.height-y)*right.width*4),y*right.width*4);
 // Preserve the renderer's actual frame before disposing its GPU resources.
